<template><div v-if="grid&&!trash" class="grid-content" :class="{'empty-grid':!items.length}"><slot v-if="!items.length" name="empty"/><div v-else class="file-grid"><article v-for="item in items" :key="key(item)" class="grid-file" :class="{selected:selected.has(key(item)),'is-inspected':ui.detail?.id===item.id}" @contextmenu="$emit('menu',$event,item)"><div class="grid-preview" @click="$emit('open',item)"><div class="preview-generic"><FileGlyph :item="item" size="large"/></div></div><input class="file-check grid-check" type="checkbox" :checked="selected.has(key(item))" :aria-label="'选择 '+item.name" @change="$emit('select',key(item))"/><div class="grid-caption"><FileGlyph :item="item"/><button class="file-name-button truncate" @click="$emit('open',item)"><NameText :item="item" :keyword="keyword"/><span class="file-secondary">{{item.displayPath||time(item.updatedAt)}}</span></button><button class="icon-button" aria-label="更多操作" @click="$emit('menu',$event,item)"><Icon name="more"/></button></div></article></div></div><div v-else class="file-table" role="table" aria-label="文件列表"><div class="list-header" role="row"><div role="columnheader"><input class="file-check" type="checkbox" :checked="all" :indeterminate.prop="some&&!all" :disabled="!items.length" aria-label="选择本页全部文件" @change="$emit('all')"/></div><div v-for="col in columns" :key="col.key" class="header-cell" role="columnheader" :aria-sort="sortBy===col.key?(sortOrder==='asc'?'ascending':'descending'):'none'"><button v-if="col.sort" class="header-sort" :class="{active:sortBy===col.key}" @click="$emit('sort',col.key)">{{col.label}}<Icon :name="sortBy===col.key?(sortOrder==='asc'?'up':'down'):'sort'" class="small"/></button><span v-else>{{col.label}}</span></div><span role="columnheader"><span class="sr-only">操作</span></span></div><div class="table-rows" role="rowgroup"><div v-for="item in items" :key="key(item)" class="file-row" role="row" tabindex="0" :class="{selected:selected.has(key(item)),'is-inspected':ui.detail?.id===item.id}" :aria-selected="selected.has(key(item))" @contextmenu="$emit('menu',$event,item)" @click="selectRow($event,item)" @keydown.enter.prevent="$emit('open',item)" @keydown.space.prevent="$emit('select',key(item))"><div role="cell"><input class="file-check" type="checkbox" :checked="selected.has(key(item))" :aria-label="'选择 '+item.name" @change="$emit('select',key(item))" @keydown.stop/></div><div class="file-name-cell" role="cell"><FileGlyph :item="item"/><button class="file-name-button truncate" :title="item.name" @click="$emit('open',item)" @keydown.stop><NameText :item="item" :keyword="keyword"/><span v-if="showLocation" class="file-secondary">{{item.displayPath||'—'}}</span></button></div><span class="cell-muted" role="cell">{{time(trash?item.deletedAt:item.updatedAt)}}</span><span class="owner-cell col-owner" role="cell"><span class="avatar">{{(outgoing?item.targetName:item.modifiedByName||'未知')?.slice(0,1)}}</span>{{outgoing?item.targetName:item.modifiedByName||'未知'}}</span><span class="cell-muted col-size" role="cell">{{item.itemType==='folder'?'—':size(item.sizeBytes)}}</span><span class="col-access" role="cell"><span class="access-label" :class="{shared:item.source!=='personal'}"><Icon :name="item.source==='personal'?'lock':'people'"/>{{trash?'可恢复':outgoing?item.permission:item.source==='workspace'?'协作空间':item.source==='shared'?(item.allowEdit?'可编辑':item.allowDownload?'可下载':'仅预览') :item.shared?'协作共享':'仅自己'}}</span></span><span class="row-action" role="cell"><button class="icon-button" :aria-label="'更多操作：'+item.name" @click="$emit('menu',$event,item)" @keydown.stop><Icon name="more"/></button></span></div></div><div class="empty-in-table" v-if="!items.length"><slot name="empty"/></div></div></template>
<script setup>
import {computed} from 'vue';import Icon from './Icon.vue';import FileGlyph from './FileGlyph.vue';import NameText from './NameText.vue';import {ui} from '../state';import {formatFileSize as size,formatTime as time} from '../../utils/formatters';
const p=defineProps({items:{default:()=>[]},selected:{default:()=>new Set()},grid:Boolean,trash:Boolean,outgoing:Boolean,search:Boolean,showLocation:Boolean,keyword:{default:''},sortBy:String,sortOrder:String});
const emit=defineEmits(['select','all','sort','open','menu']);
function selectRow(event,item){if(event.target.closest('button,input,a')||window.getSelection()?.toString())return;emit('select',key(item));}
const key=i=>i.rowKey||i.id;const all=computed(()=>p.items.length>0&&p.items.every(i=>p.selected.has(key(i)))),some=computed(()=>p.items.some(i=>p.selected.has(key(i))));
const columns=computed(()=>[{key:'name',label:'名称',sort:true},{key:p.trash?'deletedAt':'updatedAt',label:p.trash?'删除时间':'修改时间',sort:true},{key:p.outgoing?'targetName':'modifiedByName',label:p.outgoing?'共享对象':'修改者',sort:p.outgoing},{key:'sizeBytes',label:'大小',sort:!p.outgoing&&!p.search},{key:'access',label:'访问范围'}]);
</script>
